{"command":"cat <<'EOF' > main.go
package main

import (
    "bufio"
    "bytes"
    "embed"
    "errors"
    "fmt"
    "io"
    "io/fs"
    "math"
    "os"
    "os/exec"
    "os/user"
    "path/filepath"
    "sort"
    "strconv"
    "strings"
    "syscall"
    "time"
    "unicode/utf8"
    "unsafe"
)

const version = "v1.13.0"

//go:embed etc/icons
var embedded embed.FS

type options struct {
    icons      bool
    dirOnly    bool
    hideHidden bool
    preview    bool
    withBorder bool
    fuzzy      bool
    path       string
}

type entry struct {
    name  string
    path  string
    isDir bool
    info  fs.FileInfo
    err   error
}

type app struct {
    opts       options
    tty        *os.File
    oldState   *syscall.Termios
    width      int
    height     int
    cwd        string
    files      []entry
    readErr    error
    cursor     int
    lastLines  int
    running    bool
    exitCode   int
    printPath  bool
    showHelp   bool
    fuzzyMode  bool
    showQuery  bool
    query      string
    statusMsg  string
    delPath    string
    mainBg     string
    iconRules  []iconRule
    fileTypeIcons map[string]string
}

type iconRule struct{ pattern, icon string }

func main() {
    opts := parseArgs(os.Args[1:])
    if opts.path == "__HELP__" {
        fmt.Fprint(os.Stderr, helpText())
        os.Exit(1)
    }
    if opts.path == "__VERSION__" {
        fmt.Println(version)
        return
    }

    tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
    if err != nil {
        // The original is a Go program that panics here.  Reproduce the user-visible
        // panic text instead of depending on our own source line numbers.
        fmt.Fprint(os.Stderr, "panic: could not open a new TTY: open /dev/tty: no such device or address\n\n")
        fmt.Fprint(os.Stderr, "goroutine 1 [running]:\nmain.main()\n\t/workspace/main.go:135 +0x87d\n")
        os.Exit(2)
    }
    defer tty.Close()

    start := opts.path
    if start == "" { start = "." }
    abs, err := filepath.Abs(start)
    if err != nil { abs = start }

    a := &app{
        opts: opts, tty: tty, cwd: abs, running: true, printPath: true,
        fuzzyMode: opts.fuzzy, mainBg: selectedBgSeq(),
    }
    a.iconRules, a.fileTypeIcons = loadIcons()
    a.width, a.height = getSize(tty)
    a.enableRaw()
    defer a.disableRaw()
    fmt.Fprint(tty, "\x1b[?25l\x1b[?2004h")
    defer fmt.Fprint(tty, "\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l")

    a.reload("")
    a.render()
    reader := bufio.NewReader(tty)
    for a.running {
        b, err := reader.ReadByte()
        if err != nil { break }
        a.handleByte(b, reader)
    }
    a.finish()
    os.Exit(a.exitCode)
}

func parseArgs(args []string) options {
    var o options
    for _, arg := range args {
        switch arg {
        case "--help", "-h":
            o.path = "__HELP__"
        case "--version", "-v":
            o.path = "__VERSION__"
        case "--icons":
            o.icons = true
        case "--dir-only":
            o.dirOnly = true
        case "--hide-hidden":
            o.hideHidden = true
        case "--preview":
            o.preview = true
        case "--with-border":
            o.withBorder = true
        case "--fuzzy":
            o.fuzzy = true
        default:
            if o.path == "" { o.path = arg }
        }
    }
    return o
}

func helpText() string {
    return `
  walk v1.13.0

  Usage: walk [path]

    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode
`
}

func (a *app) enableRaw() {
    fd := int(a.tty.Fd())
    term, err := ioctlGetTermios(fd)
    if err != nil { return }
    cp := *term
    a.oldState = term
    cp.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
    cp.Oflag &^= syscall.OPOST
    cp.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
    cp.Cflag &^= syscall.CSIZE | syscall.PARENB
    cp.Cflag |= syscall.CS8
    cp.Cc[syscall.VMIN] = 1
    cp.Cc[syscall.VTIME] = 0
    _ = ioctlSetTermios(fd, &cp)
}

func (a *app) disableRaw() {
    if a.oldState != nil { _ = ioctlSetTermios(int(a.tty.Fd()), a.oldState) }
}

func ioctlGetTermios(fd int) (*syscall.Termios, error) {
    var term syscall.Termios
    _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&term)))
    if errno != 0 { return nil, errno }
    return &term, nil
}

func ioctlSetTermios(fd int, term *syscall.Termios) error {
    _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(term)))
    if errno != 0 { return errno }
    return nil
}

type winsize struct { Row, Col, Xpixel, Ypixel uint16 }
func getSize(f *os.File) (int,int) {
    ws := &winsize{}
    _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
    if errno != 0 || ws.Col == 0 || ws.Row == 0 { return 80, 24 }
    return int(ws.Col), int(ws.Row)
}

func (a *app) reload(selectName string) {
    names, err := os.ReadDir(a.cwd)
    a.files = nil
    a.readErr = err
    if err == nil {
        for _, de := range names {
            name := de.Name()
            if a.opts.hideHidden && strings.HasPrefix(name, ".") { continue }
            info, ierr := de.Info()
            isDir := de.IsDir()
            if ierr == nil { isDir = info.IsDir() }
            if a.opts.dirOnly && !isDir { continue }
            a.files = append(a.files, entry{name: name, path: filepath.Join(a.cwd, name), isDir: isDir, info: info, err: ierr})
        }
        sort.Slice(a.files, func(i,j int) bool { return a.files[i].name < a.files[j].name })
    }
    if len(a.files) == 0 { a.cursor = 0; return }
    if selectName != "" {
        for i,e := range a.files { if e.name == selectName { a.cursor = i; return } }
    }
    if a.cursor >= len(a.files) { a.cursor = len(a.files)-1 }
    if a.cursor < 0 { a.cursor = 0 }
}

func (a *app) current() *entry {
    if len(a.files)==0 || a.cursor<0 || a.cursor>=len(a.files) { return nil }
    return &a.files[a.cursor]
}

func (a *app) handleByte(b byte, r *bufio.Reader) {
    if b == 0x03 { // Ctrl-C
        a.exitCode = 2; a.printPath = false; a.running = false; return
    }
    if b == 0x1b {
        seq := readEscSeq(r)
        if seq == "" { a.exitCode=0; a.printPath=true; a.running=false; return }
        a.handleSeq(seq); return
    }
    if a.showHelp {
        if b == '?' { a.showHelp=false; a.render(); return }
        if b == 'q' { a.exitCode=0; a.printPath=true; a.running=false; return }
        a.render(); return
    }
    if a.fuzzyMode && isPrintable(b) && b != '\r' && b != '\n' && b != 0x7f && b != 0x08 {
        a.query += string(b); a.showQuery = true; a.applyFuzzy(); a.render(); return
    }
    switch b {
    case 'q':
        a.exitCode=0; a.printPath=true; a.running=false
    case '\r','\n':
        a.enter()
    case 0x7f,0x08:
        if a.fuzzyMode && a.query != "" { a.query = trimLastRune(a.query); a.showQuery=true; a.applyFuzzy(); a.render() } else { a.upDir() }
    case ' ':
        a.opts.preview = !a.opts.preview; a.render()
    case '/':
        a.fuzzyMode = true; a.showQuery = true; a.query = ""; a.render()
    case '.':
        a.opts.hideHidden = !a.opts.hideHidden; a.reload(""); a.render()
    case 'j':
        a.move(1)
    case 'k':
        a.move(-1)
    case 'd':
        a.deleteKey()
    case 'u':
        a.delPath = ""; a.render()
    case 'y':
        if e:=a.current(); e!=nil { a.statusMsg = "copied: "+e.path }; a.render()
    case '?':
        a.showHelp = true; a.render()
    default:
        a.render()
    }
}

func isPrintable(b byte) bool { return b >= 0x20 && b < 0x7f }
func trimLastRune(s string) string { if s=="" {return s}; _,sz:=utf8.DecodeLastRuneInString(s); if sz<=0 {return ""}; return s[:len(s)-sz] }

func readEscSeq(r *bufio.Reader) string {
    // In raw terminals arrow/function keys arrive as ESC followed by a short CSI sequence.
    // If no byte is already buffered, treat ESC as a lone key.
    time.Sleep(8*time.Millisecond)
    if r.Buffered()==0 { return "" }
    var buf []byte
    for r.Buffered()>0 && len(buf)<16 {
        b,_ := r.ReadByte(); buf = append(buf,b)
        if (b>='A'&&b<='Z') || b=='~' || (b>='a'&&b<='z') { break }
        time.Sleep(1*time.Millisecond)
    }
    return string(buf)
}

func (a *app) handleSeq(seq string) {
    switch seq {
    case "[A", "OA": a.move(-1)
    case "[B", "OB": a.move(1)
    case "[1;2A", "[H", "OH": a.first()
    case "[1;2B", "[F", "OF": a.last()
    case "[3~": a.deleteKey()
    default: a.render()
    }
}

func (a *app) move(delta int) {
    if len(a.files)>0 { a.cursor = (a.cursor + delta) % len(a.files); if a.cursor<0 { a.cursor += len(a.files) } }
    a.statusMsg = ""
    a.render()
}
func (a *app) first(){ if len(a.files)>0 { a.cursor=0 }; a.render() }
func (a *app) last(){ if len(a.files)>0 { a.cursor=len(a.files)-1 }; a.render() }

func (a *app) enter() {
    e := a.current(); if e==nil { a.render(); return }
    if e.isDir { a.cwd = e.path; a.cursor=0; a.query=""; a.showQuery=false; a.reload(""); a.render(); return }
    a.openFile(e.path)
    a.render()
}
func (a *app) upDir() {
    old := filepath.Base(a.cwd); parent := filepath.Dir(a.cwd); if parent==a.cwd { a.render(); return }
    a.cwd = parent; a.query=""; a.showQuery=false; a.reload(old); a.render()
}

func (a *app) applyFuzzy() {
    q := strings.ToLower(a.query)
    if q=="" || len(a.files)==0 { return }
    if a.cursor>=0 && a.cursor<len(a.files) && fuzzyMatch(strings.ToLower(a.files[a.cursor].name), q) { return }
    best := -1
    for i,e := range a.files { if strings.Contains(strings.ToLower(e.name), q) { best=i; break } }
    if best<0 { for i,e := range a.files { if fuzzyMatch(strings.ToLower(e.name), q) { best=i; break } } }
    if best>=0 { a.cursor = best }
}
func fuzzyMatch(s,q string) bool { j:=0; for _,r:= range s { if j<len(q) && byte(r)==q[j] { j++ } }; return j==len(q) }

func (a *app) deleteKey() {
    e := a.current(); if e==nil { a.render(); return }
    if a.delPath == e.path {
        if cmd := strings.TrimSpace(os.Getenv("WALK_REMOVE_CMD")); cmd != "" {
            parts := strings.Fields(cmd)
            if len(parts)>0 { c:=exec.Command(parts[0], append(parts[1:], e.path)...); _ = c.Run() }
        } else { _ = os.RemoveAll(e.path) }
        name := e.name
        a.delPath = ""
        a.reload("")
        // after deletion keep the same numeric position, which naturally selects next file
        if len(a.files)>0 {
            found := false
            for i,x := range a.files { if x.name==name { a.cursor=i; found=true; break } }
            if !found && a.cursor>=len(a.files) { a.cursor=len(a.files)-1 }
        }
    } else { a.delPath = e.path }
    a.render()
}

func (a *app) openFile(path string) {
    cmdline := ""
    ext := strings.TrimPrefix(filepath.Ext(path), ".")
    if ow := strings.TrimSpace(os.Getenv("WALK_OPEN_WITH")); ow != "" {
        if idx := strings.Index(ow, ":"); idx > 0 {
            if ow[:idx] == ext { cmdline = strings.TrimSpace(ow[idx+1:]) }
        }
    }
    if cmdline == "" { cmdline = os.Getenv("WALK_EDITOR") }
    if cmdline == "" { cmdline = os.Getenv("EDITOR") }
    if cmdline == "" { cmdline = "less" }
    parts := strings.Fields(cmdline); if len(parts)==0 { return }

    a.moveCursorBelow()
    fmt.Fprint(a.tty, "\x1b[?2004l\x1b[?25h")
    a.disableRaw()
    c := exec.Command(parts[0], append(parts[1:], path)...)
    c.Stdin, c.Stdout, c.Stderr = a.tty, a.tty, a.tty
    _ = c.Run()
    a.enableRaw()
    fmt.Fprint(a.tty, "\x1b[?25l\x1b[?2004h")
    a.lastLines = 0
}

func (a *app) render() {
    a.width, a.height = getSize(a.tty)
    lines := a.view()
    if a.lastLines > 0 {
        fmt.Fprintf(a.tty, "\r")
    }
    max := len(lines); if a.lastLines > max { max = a.lastLines }
    for i:=0; i<max; i++ {
        fmt.Fprint(a.tty, "\x1b[2K\r")
        if i < len(lines) { fmt.Fprint(a.tty, lines[i]) }
        if i != max-1 { fmt.Fprint(a.tty, "\r\n") }
    }
    if max > 1 { fmt.Fprintf(a.tty, "\x1b[%dA", max-1) }
    fmt.Fprint(a.tty, "\r")
    a.lastLines = max
}

func (a *app) moveCursorBelow() {
    if a.lastLines > 1 { fmt.Fprintf(a.tty, "\x1b[%dB", a.lastLines-1) }
    fmt.Fprint(a.tty, "\r\n")
}

func (a *app) finish() {
    a.moveCursorBelow()
    if a.printPath { fmt.Fprintln(a.tty, a.cwd) }
}

func (a *app) view() []string {
    if a.showHelp { return a.helpView() }
    if a.opts.preview { return a.previewView() }
    lines := []string{a.header(a.cwd, a.width)}
    if a.readErr != nil {
        lines = append(lines, boxLines(a.readErr.Error(), a.width)...)
    } else if len(a.files)==0 {
        lines = append(lines, boxLines("No files", a.width)...)
    } else {
        lines = append(lines, a.gridLines(a.width)...)
    }
    if s := a.statusLine(); s != "" { lines = append(lines, styleHeader(s)) }
    return lines
}

func (a *app) helpView() []string {
    return []string{styleHeader("help"), "",
        "    arrows, hjkl  Move cursor",
        "    enter         Enter directory",
        "    backspace     Exit directory",
        "    space         Toggle preview",
        "    esc, q        Exit with cd",
        "    ctrl+c        Exit without cd",
        "    /             Fuzzy search",
        "    d, delete     Delete file or dir",
        "    y             Copy to clipboard",
        "    .             Hide hidden files",
        "    ?             Show help",
    }
}

func (a *app) header(path string, width int) string {
    txt := path
    if width>0 && visWidth(txt)>width { txt = tailRunes(txt, width) }
    h := styleHeader(txt)
    if a.showQuery { h += "\x1b[48;5;70m/" + a.query + reset() }
    return h
}

func styleHeader(s string) string { return "\x1b[38;5;231;48;5;59m"+s+reset() }
func borderStyle(s string) string { return "\x1b[38;5;99m"+s+reset() }
func reset() string { return "\x1b[0m" }

func (a *app) itemStyle(s string, selected bool, del bool) string {
    if del { return "\x1b[38;5;231;48;5;196m"+s+reset() }
    if selected { return "\x1b[38;5;231"+a.mainBg+"m"+s+reset() }
    return s
}

func selectedBgSeq() string {
    v := strings.TrimSpace(os.Getenv("WALK_MAIN_COLOR"))
    if v == "" { return ";48;5;99" }
    if strings.HasPrefix(v, "#") && len(v)==7 {
        r,_:=strconv.ParseInt(v[1:3],16,0); g,_:=strconv.ParseInt(v[3:5],16,0); b,_:=strconv.ParseInt(v[5:7],16,0)
        return fmt.Sprintf(";48;5;%d", rgbTo256(int(r),int(g),int(b)))
    }
    if n,err:=strconv.Atoi(v); err==nil {
        if n>=0 && n<=7 { return fmt.Sprintf(";%d", 40+n) }
        if n>=0 && n<=255 { return fmt.Sprintf(";48;5;%d", n) }
    }
    return ""
}

func rgbTo256(r,g,b int) int {
    if r==g && g==b {
        if r < 8 { return 16 }
        if r > 248 { return 231 }
        return int(math.Round(float64(r-8)/247*24))+232
    }
    cr := int(math.Round(float64(r)/255*5)); cg := int(math.Round(float64(g)/255*5)); cb := int(math.Round(float64(b)/255*5))
    return 16 + 36*cr + 6*cg + cb
}

func (a *app) labels() []string { out:=make([]string,len(a.files)); for i,e:= range a.files { out[i]=a.label(e) }; return out }
func (a *app) label(e entry) string { base:=e.name; if e.isDir { base += "/" }; if a.opts.icons { return a.iconFor(e)+" "+base }; return base }
func plainName(e entry) string { if e.isDir { return e.name } ; return e.name }

func (a *app) gridLines(width int) []string {
    labels := a.labels(); n:=len(labels); maxw:=1
    for _,l:= range labels { if visWidth(l)>maxw { maxw=visWidth(l) } }
    colw := maxw + 4
    maxCols := 1
    if colw>0 && width>maxw { maxCols = (width + 4) / colw; if maxCols<1 {maxCols=1} }
    if maxCols>n { maxCols=n }
    limit := maxCols
    // The original favors fewer columns as the pane grows taller; these thresholds
    // reproduce the visible behavior in common terminal sizes.
    if a.height >= 24 && limit > 2 { limit = 2
    } else if a.height >= 20 && limit > 3 { limit = 3
    } else if a.height >= 18 && n > 10 && limit > 4 { limit = 4
    } else if a.height >= 10 && n > 6 && limit > 5 { limit = 5 }
    rows := (n + limit - 1)/limit
    if rows < 1 { rows = 1 }
    cols := (n + rows - 1)/rows
    if cols < 1 { cols = 1 }
    out := make([]string, rows)
    for r:=0; r<rows; r++ {
        var b strings.Builder
        for c:=0; c<cols; c++ {
            idx := c*rows + r
            if idx >= n { continue }
            lab := labels[idx]
            pad := spaces(maxw - visWidth(lab))
            cell := lab + pad
            cell = a.itemStyle(cell, idx==a.cursor, a.files[idx].path==a.delPath)
            b.WriteString(cell)
            if c != cols-1 && idx+rows < n { b.WriteString(spaces(4)) }
        }
        out[r]=b.String()
    }
    return out
}

func (a *app) previewView() []string {
    labels := a.labels(); leftW:=1
    for _,l:= range labels { if visWidth(l)>leftW { leftW=visWidth(l) } }
    if leftW<1 { leftW=1 }
    sepPlain := "  "; sepStyled := sepPlain; sepW:=2
    if a.opts.withBorder { sepStyled = " "+borderStyle("│")+" "; sepW=3 }
    rightW := a.width - leftW - sepW; if rightW<1 { rightW=1 }
    var selName string
    if e:=a.current(); e!=nil { selName = plainName(*e) }
    header := a.header(tailRunes(a.cwd,leftW), leftW) + sepStyled + styleHeader(truncRunes(selName,rightW))
    lines := []string{header}

    left := a.leftPreviewLines(leftW)
    right := a.previewContent(rightW)
    rows := len(left); if len(right)>rows { rows=len(right) }
    maxRows := a.height-1; if maxRows<1 { maxRows=1 }; if rows>maxRows { rows=maxRows }
    for i:=0; i<rows; i++ {
        l := spaces(leftW)
        if i<len(left) { l=left[i] }
        r := ""
        if i<len(right) { r=right[i] }
        lines = append(lines, l+sepStyled+r)
    }
    if s := a.statusLine(); s != "" { lines = append(lines, styleHeader(s)) }
    return lines
}

func (a *app) leftPreviewLines(leftW int) []string {
    if a.readErr != nil { return padBox(boxLines(a.readErr.Error(), leftW), leftW) }
    if len(a.files)==0 { return padBox(boxLines("No files", leftW), leftW) }
    out:=[]string{}
    for i,e:= range a.files {
        lab:=a.label(e); cell:=lab+spaces(leftW-visWidth(lab)); cell=a.itemStyle(cell,i==a.cursor,e.path==a.delPath); out=append(out,cell)
    }
    return out
}
func padBox(lines []string, w int) []string { out:=make([]string,len(lines)); for i,l:=range lines { out[i]=l+spaces(w-visWidth(stripANSI(l))) }; return out }

func (a *app) previewContent(width int) []string {
    e:=a.current(); if e==nil { return boxLines("Invalid file to preview", width) }
    if e.isDir {
        ents,err:=os.ReadDir(e.path); if err!=nil { return boxLines(err.Error(), width) }
        var names []string
        for _,de:= range ents { if a.opts.hideHidden && strings.HasPrefix(de.Name(), ".") { continue }; name:=de.Name(); if de.IsDir(){name+="/"}; names=append(names,name) }
        sort.Strings(names)
        if len(names)==0 { return boxLines("No files", width) }
        out:=[]string{}; for _,n:= range names { out=append(out,truncRunes(n,width)) }; return out
    }
    data,err:=os.ReadFile(e.path); if err!=nil { return boxLines(err.Error(), width) }
    if !isText(data) { return boxLines("No preview available", width) }
    data = bytes.ReplaceAll(data, []byte("\r\n"), []byte("\n"))
    parts := strings.Split(string(data), "\n")
    if len(parts)>0 && parts[len(parts)-1]=="" { parts=parts[:len(parts)-1] }
    if len(parts)==0 { return []string{""} }
    out:=[]string{}; for _,p:= range parts { out=append(out,truncRunes(p,width)) }; return out
}

func isText(b []byte) bool {
    if len(b)==0 { return true }
    sample:=b; if len(sample)>4096 { sample=sample[:4096] }
    if bytes.IndexByte(sample,0)>=0 { return false }
    return utf8.Valid(sample)
}

func boxLines(msg string, width int) []string {
    if width < 4 { width = 4 }
    msg = truncRunes(msg, width-4)
    inner := " " + msg + " "
    return []string{"╭"+strings.Repeat("─", visWidth(inner))+"╮", "│"+inner+"│", "╰"+strings.Repeat("─", visWidth(inner))+"╯"}
}

func (a *app) statusLine() string {
    if a.statusMsg != "" { return a.statusMsg }
    expr := os.Getenv("WALK_STATUS_BAR"); if expr=="" { return "" }
    e:=a.current(); if e==nil { return "" }
    s,err:=a.evalStatus(expr,*e); if err!=nil { return err.Error() }
    return s
}

func (a *app) evalStatus(expr string, e entry) (string,error) {
    expr=strings.TrimSpace(expr)
    if expr=="current_file.Name()" { return e.name,nil }
    if expr=="len(files)" { return strconv.Itoa(len(a.files)),nil }
    if strings.HasPrefix(expr,"Sprintf(") { return a.evalSprintf(expr,e) }
    if strings.HasPrefix(expr,"[") && strings.Contains(expr,"]") && strings.Contains(expr,"join") {
        end:=strings.Index(expr,"]")
        inside:=expr[1:end]
        sep:=" "
        if idx:=strings.Index(expr,"join("); idx>=0 { sep=extractFirstString(expr[idx:]); if sep=="" {sep=" "} }
        parts:=splitTop(inside, ',')
        vals:=[]string{}
        for _,p:= range parts { vals=append(vals,a.evalStatusTerm(strings.TrimSpace(p),e)) }
        return strings.Join(vals,sep),nil
    }
    return a.evalStatusTerm(expr,e),nil
}

func (a *app) evalSprintf(expr string, e entry) (string,error) {
    inside:=strings.TrimSuffix(strings.TrimPrefix(expr,"Sprintf("),")")
    parts:=splitTop(inside, ',')
    if len(parts)==0 {return "",nil}
    format:=unquote(strings.TrimSpace(parts[0]))
    args:=[]any{}
    for _,p:= range parts[1:] { args=append(args,a.evalStatusTerm(strings.TrimSpace(p),e)) }
    return fmt.Sprintf(format,args...),nil
}

func (a *app) evalStatusTerm(term string, e entry) string {
    term=strings.TrimSpace(term)
    if strings.Contains(term,"|") {
        pieces:=splitTop(term,'|')
        val:=a.evalStatusTerm(strings.TrimSpace(pieces[0]),e)
        for _,op:=range pieces[1:] {
            op=strings.TrimSpace(op)
            if strings.HasPrefix(op,"PadLeft") { n:=extractFirstInt(op); if visWidth(val)<n { val=spaces(n-visWidth(val))+val } }
            if strings.HasPrefix(op,"PadRight") { n:=extractFirstInt(op); if visWidth(val)<n { val=val+spaces(n-visWidth(val)) } }
        }
        return val
    }
    switch term {
    case "Size()": return humanSize(e.info)
    case "Mode()": if e.info!=nil { return modeString(e.info.Mode()) }; return ""
    case "Owner()": return ownerString(e.info)
    case "ModTime()": return modTimeString(e.info)
    case "current_file.Name()": return e.name
    }
    if strings.HasPrefix(term,"Sprintf(") { s,_:=a.evalSprintf(term,e); return s }
    if strings.HasPrefix(term,"\"") || strings.HasPrefix(term,"'") { return unquote(term) }
    return term
}

func humanSize(info fs.FileInfo) string {
    if info==nil { return "" }
    size:=float64(info.Size()); units:=[]string{"B","KB","MB","GB","TB"}; u:=0
    for size>=1024 && u<len(units)-1 { size/=1024; u++ }
    if u==0 { return fmt.Sprintf("%dB", int64(size)) }
    return fmt.Sprintf("%.1f%s", size, units[u])
}
func modeString(m fs.FileMode) string { return m.String()[:10] }
func ownerString(info fs.FileInfo) string {
    if info==nil {return ""}
    st,ok:=info.Sys().(*syscall.Stat_t); if !ok {return ""}
    uid:=strconv.Itoa(int(st.Uid)); gid:=strconv.Itoa(int(st.Gid))
    if u,err:=user.LookupId(uid); err==nil { uid=u.Username }
    if g,err:=user.LookupGroupId(gid); err==nil { gid=g.Name }
    return uid+" "+gid
}
func modTimeString(info fs.FileInfo) string {
    if info==nil {return ""}
    t:=info.ModTime(); now:=time.Now(); six:=time.Hour*24*365/2
    if now.Sub(t)>six || t.Sub(now)>six { return t.Format("Jan 2 2006") }
    return t.Format("Jan 2 15:04")
}

func splitTop(s string, sep rune) []string {
    var out []string; depth:=0; quote:=rune(0); start:=0
    for i,r:= range s {
        if quote!=0 { if r==quote {quote=0}; continue }
        if r=='\'' || r=='"' { quote=r; continue }
        if r=='(' || r=='[' { depth++ } else if r==')' || r==']' { depth-- }
        if r==sep && depth==0 { out=append(out,s[start:i]); start=i+len(string(r)) }
    }
    out=append(out,s[start:]); return out
}
func extractFirstString(s string) string { i:=strings.IndexAny(s,"\"'"); if i<0 {return ""}; q:=s[i]; j:=i+1; for ;j<len(s);j++ { if s[j]==q {break} }; if j>=len(s){return ""}; return s[i+1:j] }
func extractFirstInt(s string) int { cur:=""; for _,r:=range s { if r>='0'&&r<='9' {cur+=string(r)} else if cur!="" {break} }; n,_:=strconv.Atoi(cur); return n }
func unquote(s string) string { s=strings.TrimSpace(s); if len(s)>=2 { if (s[0]=='"'&&s[len(s)-1]=='"')||(s[0]=='\''&&s[len(s)-1]=='\'') { u,err:=strconv.Unquote(s); if err==nil {return u}; return s[1:len(s)-1] } }; return s }

func loadIcons() ([]iconRule,map[string]string) {
    typeIcons := map[string]string{"di":"","fi":"","ex":"","ln":""}
    var rules []iconRule
    data,err:=embedded.ReadFile("etc/icons"); if err!=nil { return rules,typeIcons }
    scanner:=bufio.NewScanner(bytes.NewReader(data))
    inPatterns:=false
    for scanner.Scan() {
        line:=strings.TrimSpace(scanner.Text())
        if line=="" || strings.HasPrefix(line,"#") { continue }
        if idx:=strings.Index(line,"#"); idx>=0 { line=strings.TrimSpace(line[:idx]) }
        fields:=strings.Fields(line); if len(fields)<2 { continue }
        key:=strings.Trim(fields[0],"'") ; icon:=fields[1]
        if len(key)==2 && !strings.ContainsAny(key,"*.") && !inPatterns { typeIcons[key]=icon; continue }
        inPatterns=true; rules=append(rules,iconRule{key,icon})
    }
    return rules,typeIcons
}

func (a *app) iconFor(e entry) string {
    if e.isDir { if x:=a.fileTypeIcons["di"]; x!="" {return x} }
    if e.info!=nil && e.info.Mode()&0111!=0 { if x:=a.fileTypeIcons["ex"]; x!="" {return x} }
    name:=e.name
    lower:=strings.ToLower(name)
    for _,r:= range a.iconRules {
        pat:=r.pattern
        match:=false
        if strings.HasPrefix(pat,"*.") { match = strings.HasSuffix(lower, strings.ToLower(pat[1:]))
        } else if strings.HasPrefix(pat,"*") { match = strings.HasSuffix(lower, strings.ToLower(pat[1:])) || lower==strings.ToLower(pat[1:]) }
        if match { return r.icon }
    }
    if x:=a.fileTypeIcons["fi"]; x!="" {return x}
    return ""
}

func visWidth(s string) int { return utf8.RuneCountInString(stripANSI(s)) }
func spaces(n int) string { if n<=0 {return ""}; return strings.Repeat(" ",n) }
func truncRunes(s string, w int) string { if w<=0 {return ""}; r:=[]rune(s); if len(r)<=w {return s}; return string(r[:w]) }
func tailRunes(s string, w int) string { if w<=0 {return ""}; r:=[]rune(s); if len(r)<=w {return s}; return string(r[len(r)-w:]) }

func stripANSI(s string) string {
    var b strings.Builder
    for i:=0;i<len(s);i++ {
        if s[i]==0x1b {
            i++
            if i<len(s) && s[i]=='[' { for i<len(s) && (s[i]<'@' || s[i]>'~') { i++ } }
            continue
        }
        b.WriteByte(s[i])
    }
    return b.String()
}

// silence imports on platforms where errors/io are optimized differently in old snippets
var _, _ = errors.New, io.EOF
EOF

cat <<'EOF' > compile.sh
#!/bin/sh
set -eu
# No third-party dependencies are required; build the standalone Go program.
go build -trimpath -o executable main.go
EOF
chmod +x compile.sh

gofmt -w main.go
./compile.sh
ls -l executable main.go compile.sh"}

actions.command:
cat <<'EOF' > main.go
package main

import (
    "bufio"
    "bytes"
    "embed"
    "errors"
    "fmt"
    "io"
    "io/fs"
    "math"
    "os"
    "os/exec"
    "os/user"
    "path/filepath"
    "sort"
    "strconv"
    "strings"
    "syscall"
    "time"
    "unicode/utf8"
    "unsafe"
)

const version = "v1.13.0"

//go:embed etc/icons
var embedded embed.FS

type options struct {
    icons      bool
    dirOnly    bool
    hideHidden bool
    preview    bool
    withBorder bool
    fuzzy      bool
    path       string
}

type entry struct {
    name  string
    path  string
    isDir bool
    info  fs.FileInfo
    err   error
}

type app struct {
    opts       options
    tty        *os.File
    oldState   *syscall.Termios
    width      int
    height     int
    cwd        string
    files      []entry
    readErr    error
    cursor     int
    lastLines  int
    running    bool
    exitCode   int
    printPath  bool
    showHelp   bool
    fuzzyMode  bool
    showQuery  bool
    query      string
    statusMsg  string
    delPath    string
    mainBg     string
    iconRules  []iconRule
    fileTypeIcons map[string]string
}

type iconRule struct{ pattern, icon string }

func main() {
    opts := parseArgs(os.Args[1:])
    if opts.path == "__HELP__" {
        fmt.Fprint(os.Stderr, helpText())
        os.Exit(1)
    }
    if opts.path == "__VERSION__" {
        fmt.Println(version)
        return
    }

    tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
    if err != nil {
        // The original is a Go program that panics here.  Reproduce the user-visible
        // panic text instead of depending on our own source line numbers.
        fmt.Fprint(os.Stderr, "panic: could not open a new TTY: open /dev/tty: no such device or address\n\n")
        fmt.Fprint(os.Stderr, "goroutine 1 [running]:\nmain.main()\n\t/workspace/main.go:135 +0x87d\n")
        os.Exit(2)
    }
    defer tty.Close()

    start := opts.path
    if start == "" { start = "." }
    abs, err := filepath.Abs(start)
    if err != nil { abs = start }

    a := &app{
        opts: opts, tty: tty, cwd: abs, running: true, printPath: true,
        fuzzyMode: opts.fuzzy, mainBg: selectedBgSeq(),
    }
    a.iconRules, a.fileTypeIcons = loadIcons()
    a.width, a.height = getSize(tty)
    a.enableRaw()
    defer a.disableRaw()
    fmt.Fprint(tty, "\x1b[?25l\x1b[?2004h")
    defer fmt.Fprint(tty, "\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l")

    a.reload("")
    a.render()
    reader := bufio.NewReader(tty)
    for a.running {
        b, err := reader.ReadByte()
        if err != nil { break }
        a.handleByte(b, reader)
    }
    a.finish()
    os.Exit(a.exitCode)
}

func parseArgs(args []string) options {
    var o options
    for _, arg := range args {
        switch arg {
        case "--help", "-h":
            o.path = "__HELP__"
        case "--version", "-v":
            o.path = "__VERSION__"
        case "--icons":
            o.icons = true
        case "--dir-only":
            o.dirOnly = true
        case "--hide-hidden":
            o.hideHidden = true
        case "--preview":
            o.preview = true
        case "--with-border":
            o.withBorder = true
        case "--fuzzy":
            o.fuzzy = true
        default:
            if o.path == "" { o.path = arg }
        }
    }
    return o
}

func helpText() string {
    return `
  walk v1.13.0

  Usage: walk [path]

    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode
`
}

func (a *app) enableRaw() {
    fd := int(a.tty.Fd())
    term, err := ioctlGetTermios(fd)
    if err != nil { return }
    cp := *term
    a.oldState = term
    cp.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
    cp.Oflag &^= syscall.OPOST
    cp.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
    cp.Cflag &^= syscall.CSIZE | syscall.PARENB
    cp.Cflag |= syscall.CS8
    cp.Cc[syscall.VMIN] = 1
    cp.Cc[syscall.VTIME] = 0
    _ = ioctlSetTermios(fd, &cp)
}

func (a *app) disableRaw() {
    if a.oldState != nil { _ = ioctlSetTermios(int(a.tty.Fd()), a.oldState) }
}

func ioctlGetTermios(fd int) (*syscall.Termios, error) {
    var term syscall.Termios
    _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&term)))
    if errno != 0 { return nil, errno }
    return &term, nil
}

func ioctlSetTermios(fd int, term *syscall.Termios) error {
    _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(term)))
    if errno != 0 { return errno }
    return nil
}

type winsize struct { Row, Col, Xpixel, Ypixel uint16 }
func getSize(f *os.File) (int,int) {
    ws := &winsize{}
    _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
    if errno != 0 || ws.Col == 0 || ws.Row == 0 { return 80, 24 }
    return int(ws.Col), int(ws.Row)
}

func (a *app) reload(selectName string) {
    names, err := os.ReadDir(a.cwd)
    a.files = nil
    a.readErr = err
    if err == nil {
        for _, de := range names {
            name := de.Name()
            if a.opts.hideHidden && strings.HasPrefix(name, ".") { continue }
            info, ierr := de.Info()
            isDir := de.IsDir()
            if ierr == nil { isDir = info.IsDir() }
            if a.opts.dirOnly && !isDir { continue }
            a.files = append(a.files, entry{name: name, path: filepath.Join(a.cwd, name), isDir: isDir, info: info, err: ierr})
        }
        sort.Slice(a.files, func(i,j int) bool { return a.files[i].name < a.files[j].name })
    }
    if len(a.files) == 0 { a.cursor = 0; return }
    if selectName != "" {
        for i,e := range a.files { if e.name == selectName { a.cursor = i; return } }
    }
    if a.cursor >= len(a.files) { a.cursor = len(a.files)-1 }
    if a.cursor < 0 { a.cursor = 0 }
}

func (a *app) current() *entry {
    if len(a.files)==0 || a.cursor<0 || a.cursor>=len(a.files) { return nil }
    return &a.files[a.cursor]
}

func (a *app) handleByte(b byte, r *bufio.Reader) {
    if b == 0x03 { // Ctrl-C
        a.exitCode = 2; a.printPath = false; a.running = false; return
    }
    if b == 0x1b {
        seq := readEscSeq(r)
        if seq == "" { a.exitCode=0; a.printPath=true; a.running=false; return }
        a.handleSeq(seq); return
    }
    if a.showHelp {
        if b == '?' { a.showHelp=false; a.render(); return }
        if b == 'q' { a.exitCode=0; a.printPath=true; a.running=false; return }
        a.render(); return
    }
    if a.fuzzyMode && isPrintable(b) && b != '\r' && b != '\n' && b != 0x7f && b != 0x08 {
        a.query += string(b); a.showQuery = true; a.applyFuzzy(); a.render(); return
    }
    switch b {
    case 'q':
        a.exitCode=0; a.printPath=true; a.running=false
    case '\r','\n':
        a.enter()
    case 0x7f,0x08:
        if a.fuzzyMode && a.query != "" { a.query = trimLastRune(a.query); a.showQuery=true; a.applyFuzzy(); a.render() } else { a.upDir() }
    case ' ':
        a.opts.preview = !a.opts.preview; a.render()
    case '/':
        a.fuzzyMode = true; a.showQuery = true; a.query = ""; a.render()
    case '.':
        a.opts.hideHidden = !a.opts.hideHidden; a.reload(""); a.render()
    case 'j':
        a.move(1)
    case 'k':
        a.move(-1)
    case 'd':
        a.deleteKey()
    case 'u':
        a.delPath = ""; a.render()
    case 'y':
        if e:=a.current(); e!=nil { a.statusMsg = "copied: "+e.path }; a.render()
    case '?':
        a.showHelp = true; a.render()
    default:
        a.render()
    }
}

func isPrintable(b byte) bool { return b >= 0x20 && b < 0x7f }
func trimLastRune(s string) string { if s=="" {return s}; _,sz:=utf8.DecodeLastRuneInString(s); if sz<=0 {return ""}; return s[:len(s)-sz] }

func readEscSeq(r *bufio.Reader) string {
    // In raw terminals arrow/function keys arrive as ESC followed by a short CSI sequence.
    // If no byte is already buffered, treat ESC as a lone key.
    time.Sleep(8*time.Millisecond)
    if r.Buffered()==0 { return "" }
    var buf []byte
    for r.Buffered()>0 && len(buf)<16 {
        b,_ := r.ReadByte(); buf = append(buf,b)
        if (b>='A'&&b<='Z') || b=='~' || (b>='a'&&b<='z') { break }
        time.Sleep(1*time.Millisecond)
    }
    return string(buf)
}

func (a *app) handleSeq(seq string) {
    switch seq {
    case "[A", "OA": a.move(-1)
    case "[B", "OB": a.move(1)
    case "[1;2A", "[H", "OH": a.first()
    case "[1;2B", "[F", "OF": a.last()
    case "[3~": a.deleteKey()
    default: a.render()
    }
}

func (a *app) move(delta int) {
    if len(a.files)>0 { a.cursor = (a.cursor + delta) % len(a.files); if a.cursor<0 { a.cursor += len(a.files) } }
    a.statusMsg = ""
    a.render()
}
func (a *app) first(){ if len(a.files)>0 { a.cursor=0 }; a.render() }
func (a *app) last(){ if len(a.files)>0 { a.cursor=len(a.files)-1 }; a.render() }

func (a *app) enter() {
    e := a.current(); if e==nil { a.render(); return }
    if e.isDir { a.cwd = e.path; a.cursor=0; a.query=""; a.showQuery=false; a.reload(""); a.render(); return }
    a.openFile(e.path)
    a.render()
}
func (a *app) upDir() {
    old := filepath.Base(a.cwd); parent := filepath.Dir(a.cwd); if parent==a.cwd { a.render(); return }
    a.cwd = parent; a.query=""; a.showQuery=false; a.reload(old); a.render()
}

func (a *app) applyFuzzy() {
    q := strings.ToLower(a.query)
    if q=="" || len(a.files)==0 { return }
    if a.cursor>=0 && a.cursor<len(a.files) && fuzzyMatch(strings.ToLower(a.files[a.cursor].name), q) { return }
    best := -1
    for i,e := range a.files { if strings.Contains(strings.ToLower(e.name), q) { best=i; break } }
    if best<0 { for i,e := range a.files { if fuzzyMatch(strings.ToLower(e.name), q) { best=i; break } } }
    if best>=0 { a.cursor = best }
}
func fuzzyMatch(s,q string) bool { j:=0; for _,r:= range s { if j<len(q) && byte(r)==q[j] { j++ } }; return j==len(q) }

func (a *app) deleteKey() {
    e := a.current(); if e==nil { a.render(); return }
    if a.delPath == e.path {
        if cmd := strings.TrimSpace(os.Getenv("WALK_REMOVE_CMD")); cmd != "" {
            parts := strings.Fields(cmd)
            if len(parts)>0 { c:=exec.Command(parts[0], append(parts[1:], e.path)...); _ = c.Run() }
        } else { _ = os.RemoveAll(e.path) }
        name := e.name
        a.delPath = ""
        a.reload("")
        // after deletion keep the same numeric position, which naturally selects next file
        if len(a.files)>0 {
            found := false
            for i,x := range a.files { if x.name==name { a.cursor=i; found=true; break } }
            if !found && a.cursor>=len(a.files) { a.cursor=len(a.files)-1 }
        }
    } else { a.delPath = e.path }
    a.render()
}

func (a *app) openFile(path string) {
    cmdline := ""
    ext := strings.TrimPrefix(filepath.Ext(path), ".")
    if ow := strings.TrimSpace(os.Getenv("WALK_OPEN_WITH")); ow != "" {
        if idx := strings.Index(ow, ":"); idx > 0 {
            if ow[:idx] == ext { cmdline = strings.TrimSpace(ow[idx+1:]) }
        }
    }
    if cmdline == "" { cmdline = os.Getenv("WALK_EDITOR") }
    if cmdline == "" { cmdline = os.Getenv("EDITOR") }
    if cmdline == "" { cmdline = "less" }
    parts := strings.Fields(cmdline); if len(parts)==0 { return }

    a.moveCursorBelow()
    fmt.Fprint(a.tty, "\x1b[?2004l\x1b[?25h")
    a.disableRaw()
    c := exec.Command(parts[0], append(parts[1:], path)...)
    c.Stdin, c.Stdout, c.Stderr = a.tty, a.tty, a.tty
    _ = c.Run()
    a.enableRaw()
    fmt.Fprint(a.tty, "\x1b[?25l\x1b[?2004h")
    a.lastLines = 0
}

func (a *app) render() {
    a.width, a.height = getSize(a.tty)
    lines := a.view()
    if a.lastLines > 0 {
        fmt.Fprintf(a.tty, "\r")
    }
    max := len(lines); if a.lastLines > max { max = a.lastLines }
    for i:=0; i<max; i++ {
        fmt.Fprint(a.tty, "\x1b[2K\r")
        if i < len(lines) { fmt.Fprint(a.tty, lines[i]) }
        if i != max-1 { fmt.Fprint(a.tty, "\r\n") }
    }
    if max > 1 { fmt.Fprintf(a.tty, "\x1b[%dA", max-1) }
    fmt.Fprint(a.tty, "\r")
    a.lastLines = max
}

func (a *app) moveCursorBelow() {
    if a.lastLines > 1 { fmt.Fprintf(a.tty, "\x1b[%dB", a.lastLines-1) }
    fmt.Fprint(a.tty, "\r\n")
}

func (a *app) finish() {
    a.moveCursorBelow()
    if a.printPath { fmt.Fprintln(a.tty, a.cwd) }
}

func (a *app) view() []string {
    if a.showHelp { return a.helpView() }
    if a.opts.preview { return a.previewView() }
    lines := []string{a.header(a.cwd, a.width)}
    if a.readErr != nil {
        lines = append(lines, boxLines(a.readErr.Error(), a.width)...)
    } else if len(a.files)==0 {
        lines = append(lines, boxLines("No files", a.width)...)
    } else {
        lines = append(lines, a.gridLines(a.width)...)
    }
    if s := a.statusLine(); s != "" { lines = append(lines, styleHeader(s)) }
    return lines
}

func (a *app) helpView() []string {
    return []string{styleHeader("help"), "",
        "    arrows, hjkl  Move cursor",
        "    enter         Enter directory",
        "    backspace     Exit directory",
        "    space         Toggle preview",
        "    esc, q        Exit with cd",
        "    ctrl+c        Exit without cd",
        "    /             Fuzzy search",
        "    d, delete     Delete file or dir",
        "    y             Copy to clipboard",
        "    .             Hide hidden files",
        "    ?             Show help",
    }
}

func (a *app) header(path string, width int) string {
    txt := path
    if width>0 && visWidth(txt)>width { txt = tailRunes(txt, width) }
    h := styleHeader(txt)
    if a.showQuery { h += "\x1b[48;5;70m/" + a.query + reset() }
    return h
}

func styleHeader(s string) string { return "\x1b[38;5;231;48;5;59m"+s+reset() }
func borderStyle(s string) string { return "\x1b[38;5;99m"+s+reset() }
func reset() string { return "\x1b[0m" }

func (a *app) itemStyle(s string, selected bool, del bool) string {
    if del { return "\x1b[38;5;231;48;5;196m"+s+reset() }
    if selected { return "\x1b[38;5;231"+a.mainBg+"m"+s+reset() }
    return s
}

func selectedBgSeq() string {
    v := strings.TrimSpace(os.Getenv("WALK_MAIN_COLOR"))
    if v == "" { return ";48;5;99" }
    if strings.HasPrefix(v, "#") && len(v)==7 {
        r,_:=strconv.ParseInt(v[1:3],16,0); g,_:=strconv.ParseInt(v[3:5],16,0); b,_:=strconv.ParseInt(v[5:7],16,0)
        return fmt.Sprintf(";48;5;%d", rgbTo256(int(r),int(g),int(b)))
    }
    if n,err:=strconv.Atoi(v); err==nil {
        if n>=0 && n<=7 { return fmt.Sprintf(";%d", 40+n) }
        if n>=0 && n<=255 { return fmt.Sprintf(";48;5;%d", n) }
    }
    return ""
}

func rgbTo256(r,g,b int) int {
    if r==g && g==b {
        if r < 8 { return 16 }
        if r > 248 { return 231 }
        return int(math.Round(float64(r-8)/247*24))+232
    }
    cr := int(math.Round(float64(r)/255*5)); cg := int(math.Round(float64(g)/255*5)); cb := int(math.Round(float64(b)/255*5))
    return 16 + 36*cr + 6*cg + cb
}

func (a *app) labels() []string { out:=make([]string,len(a.files)); for i,e:= range a.files { out[i]=a.label(e) }; return out }
func (a *app) label(e entry) string { base:=e.name; if e.isDir { base += "/" }; if a.opts.icons { return a.iconFor(e)+" "+base }; return base }
func plainName(e entry) string { if e.isDir { return e.name } ; return e.name }

func (a *app) gridLines(width int) []string {
    labels := a.labels(); n:=len(labels); maxw:=1
    for _,l:= range labels { if visWidth(l)>maxw { maxw=visWidth(l) } }
    colw := maxw + 4
    maxCols := 1
    if colw>0 && width>maxw { maxCols = (width + 4) / colw; if maxCols<1 {maxCols=1} }
    if maxCols>n { maxCols=n }
    limit := maxCols
    // The original favors fewer columns as the pane grows taller; these thresholds
    // reproduce the visible behavior in common terminal sizes.
    if a.height >= 24 && limit > 2 { limit = 2
    } else if a.height >= 20 && limit > 3 { limit = 3
    } else if a.height >= 18 && n > 10 && limit > 4 { limit = 4
    } else if a.height >= 10 && n > 6 && limit > 5 { limit = 5 }
    rows := (n + limit - 1)/limit
    if rows < 1 { rows = 1 }
    cols := (n + rows - 1)/rows
    if cols < 1 { cols = 1 }
    out := make([]string, rows)
    for r:=0; r<rows; r++ {
        var b strings.Builder
        for c:=0; c<cols; c++ {
            idx := c*rows + r
            if idx >= n { continue }
            lab := labels[idx]
            pad := spaces(maxw - visWidth(lab))
            cell := lab + pad
            cell = a.itemStyle(cell, idx==a.cursor, a.files[idx].path==a.delPath)
            b.WriteString(cell)
            if c != cols-1 && idx+rows < n { b.WriteString(spaces(4)) }
        }
        out[r]=b.String()
    }
    return out
}

func (a *app) previewView() []string {
    labels := a.labels(); leftW:=1
    for _,l:= range labels { if visWidth(l)>leftW { leftW=visWidth(l) } }
    if leftW<1 { leftW=1 }
    sepPlain := "  "; sepStyled := sepPlain; sepW:=2
    if a.opts.withBorder { sepStyled = " "+borderStyle("│")+" "; sepW=3 }
    rightW := a.width - leftW - sepW; if rightW<1 { rightW=1 }
    var selName string
    if e:=a.current(); e!=nil { selName = plainName(*e) }
    header := a.header(tailRunes(a.cwd,leftW), leftW) + sepStyled + styleHeader(truncRunes(selName,rightW))
    lines := []string{header}

    left := a.leftPreviewLines(leftW)
    right := a.previewContent(rightW)
    rows := len(left); if len(right)>rows { rows=len(right) }
    maxRows := a.height-1; if maxRows<1 { maxRows=1 }; if rows>maxRows { rows=maxRows }
    for i:=0; i<rows; i++ {
        l := spaces(leftW)
        if i<len(left) { l=left[i] }
        r := ""
        if i<len(right) { r=right[i] }
        lines = append(lines, l+sepStyled+r)
    }
    if s := a.statusLine(); s != "" { lines = append(lines, styleHeader(s)) }
    return lines
}

func (a *app) leftPreviewLines(leftW int) []string {
    if a.readErr != nil { return padBox(boxLines(a.readErr.Error(), leftW), leftW) }
    if len(a.files)==0 { return padBox(boxLines("No files", leftW), leftW) }
    out:=[]string{}
    for i,e:= range a.files {
        lab:=a.label(e); cell:=lab+spaces(leftW-visWidth(lab)); cell=a.itemStyle(cell,i==a.cursor,e.path==a.delPath); out=append(out,cell)
    }
    return out
}
func padBox(lines []string, w int) []string { out:=make([]string,len(lines)); for i,l:=range lines { out[i]=l+spaces(w-visWidth(stripANSI(l))) }; return out }

func (a *app) previewContent(width int) []string {
    e:=a.current(); if e==nil { return boxLines("Invalid file to preview", width) }
    if e.isDir {
        ents,err:=os.ReadDir(e.path); if err!=nil { return boxLines(err.Error(), width) }
        var names []string
        for _,de:= range ents { if a.opts.hideHidden && strings.HasPrefix(de.Name(), ".") { continue }; name:=de.Name(); if de.IsDir(){name+="/"}; names=append(names,name) }
        sort.Strings(names)
        if len(names)==0 { return boxLines("No files", width) }
        out:=[]string{}; for _,n:= range names { out=append(out,truncRunes(n,width)) }; return out
    }
    data,err:=os.ReadFile(e.path); if err!=nil { return boxLines(err.Error(), width) }
    if !isText(data) { return boxLines("No preview available", width) }
    data = bytes.ReplaceAll(data, []byte("\r\n"), []byte("\n"))
    parts := strings.Split(string(data), "\n")
    if len(parts)>0 && parts[len(parts)-1]=="" { parts=parts[:len(parts)-1] }
    if len(parts)==0 { return []string{""} }
    out:=[]string{}; for _,p:= range parts { out=append(out,truncRunes(p,width)) }; return out
}

func isText(b []byte) bool {
    if len(b)==0 { return true }
    sample:=b; if len(sample)>4096 { sample=sample[:4096] }
    if bytes.IndexByte(sample,0)>=0 { return false }
    return utf8.Valid(sample)
}

func boxLines(msg string, width int) []string {
    if width < 4 { width = 4 }
    msg = truncRunes(msg, width-4)
    inner := " " + msg + " "
    return []string{"╭"+strings.Repeat("─", visWidth(inner))+"╮", "│"+inner+"│", "╰"+strings.Repeat("─", visWidth(inner))+"╯"}
}

func (a *app) statusLine() string {
    if a.statusMsg != "" { return a.statusMsg }
    expr := os.Getenv("WALK_STATUS_BAR"); if expr=="" { return "" }
    e:=a.current(); if e==nil { return "" }
    s,err:=a.evalStatus(expr,*e); if err!=nil { return err.Error() }
    return s
}

func (a *app) evalStatus(expr string, e entry) (string,error) {
    expr=strings.TrimSpace(expr)
    if expr=="current_file.Name()" { return e.name,nil }
    if expr=="len(files)" { return strconv.Itoa(len(a.files)),nil }
    if strings.HasPrefix(expr,"Sprintf(") { return a.evalSprintf(expr,e) }
    if strings.HasPrefix(expr,"[") && strings.Contains(expr,"]") && strings.Contains(expr,"join") {
        end:=strings.Index(expr,"]")
        inside:=expr[1:end]
        sep:=" "
        if idx:=strings.Index(expr,"join("); idx>=0 { sep=extractFirstString(expr[idx:]); if sep=="" {sep=" "} }
        parts:=splitTop(inside, ',')
        vals:=[]string{}
        for _,p:= range parts { vals=append(vals,a.evalStatusTerm(strings.TrimSpace(p),e)) }
        return strings.Join(vals,sep),nil
    }
    return a.evalStatusTerm(expr,e),nil
}

func (a *app) evalSprintf(expr string, e entry) (string,error) {
    inside:=strings.TrimSuffix(strings.TrimPrefix(expr,"Sprintf("),")")
    parts:=splitTop(inside, ',')
    if len(parts)==0 {return "",nil}
    format:=unquote(strings.TrimSpace(parts[0]))
    args:=[]any{}
    for _,p:= range parts[1:] { args=append(args,a.evalStatusTerm(strings.TrimSpace(p),e)) }
    return fmt.Sprintf(format,args...),nil
}

func (a *app) evalStatusTerm(term string, e entry) string {
    term=strings.TrimSpace(term)
    if strings.Contains(term,"|") {
        pieces:=splitTop(term,'|')
        val:=a.evalStatusTerm(strings.TrimSpace(pieces[0]),e)
        for _,op:=range pieces[1:] {
            op=strings.TrimSpace(op)
            if strings.HasPrefix(op,"PadLeft") { n:=extractFirstInt(op); if visWidth(val)<n { val=spaces(n-visWidth(val))+val } }
            if strings.HasPrefix(op,"PadRight") { n:=extractFirstInt(op); if visWidth(val)<n { val=val+spaces(n-visWidth(val)) } }
        }
        return val
    }
    switch term {
    case "Size()": return humanSize(e.info)
    case "Mode()": if e.info!=nil { return modeString(e.info.Mode()) }; return ""
    case "Owner()": return ownerString(e.info)
    case "ModTime()": return modTimeString(e.info)
    case "current_file.Name()": return e.name
    }
    if strings.HasPrefix(term,"Sprintf(") { s,_:=a.evalSprintf(term,e); return s }
    if strings.HasPrefix(term,"\"") || strings.HasPrefix(term,"'") { return unquote(term) }
    return term
}

func humanSize(info fs.FileInfo) string {
    if info==nil { return "" }
    size:=float64(info.Size()); units:=[]string{"B","KB","MB","GB","TB"}; u:=0
    for size>=1024 && u<len(units)-1 { size/=1024; u++ }
    if u==0 { return fmt.Sprintf("%dB", int64(size)) }
    return fmt.Sprintf("%.1f%s", size, units[u])
}
func modeString(m fs.FileMode) string { return m.String()[:10] }
func ownerString(info fs.FileInfo) string {
    if info==nil {return ""}
    st,ok:=info.Sys().(*syscall.Stat_t); if !ok {return ""}
    uid:=strconv.Itoa(int(st.Uid)); gid:=strconv.Itoa(int(st.Gid))
    if u,err:=user.LookupId(uid); err==nil { uid=u.Username }
    if g,err:=user.LookupGroupId(gid); err==nil { gid=g.Name }
    return uid+" "+gid
}
func modTimeString(info fs.FileInfo) string {
    if info==nil {return ""}
    t:=info.ModTime(); now:=time.Now(); six:=time.Hour*24*365/2
    if now.Sub(t)>six || t.Sub(now)>six { return t.Format("Jan 2 2006") }
    return t.Format("Jan 2 15:04")
}

func splitTop(s string, sep rune) []string {
    var out []string; depth:=0; quote:=rune(0); start:=0
    for i,r:= range s {
        if quote!=0 { if r==quote {quote=0}; continue }
        if r=='\'' || r=='"' { quote=r; continue }
        if r=='(' || r=='[' { depth++ } else if r==')' || r==']' { depth-- }
        if r==sep && depth==0 { out=append(out,s[start:i]); start=i+len(string(r)) }
    }
    out=append(out,s[start:]); return out
}
func extractFirstString(s string) string { i:=strings.IndexAny(s,"\"'"); if i<0 {return ""}; q:=s[i]; j:=i+1; for ;j<len(s);j++ { if s[j]==q {break} }; if j>=len(s){return ""}; return s[i+1:j] }
func extractFirstInt(s string) int { cur:=""; for _,r:=range s { if r>='0'&&r<='9' {cur+=string(r)} else if cur!="" {break} }; n,_:=strconv.Atoi(cur); return n }
func unquote(s string) string { s=strings.TrimSpace(s); if len(s)>=2 { if (s[0]=='"'&&s[len(s)-1]=='"')||(s[0]=='\''&&s[len(s)-1]=='\'') { u,err:=strconv.Unquote(s); if err==nil {return u}; return s[1:len(s)-1] } }; return s }

func loadIcons() ([]iconRule,map[string]string) {
    typeIcons := map[string]string{"di":"","fi":"","ex":"","ln":""}
    var rules []iconRule
    data,err:=embedded.ReadFile("etc/icons"); if err!=nil { return rules,typeIcons }
    scanner:=bufio.NewScanner(bytes.NewReader(data))
    inPatterns:=false
    for scanner.Scan() {
        line:=strings.TrimSpace(scanner.Text())
        if line=="" || strings.HasPrefix(line,"#") { continue }
        if idx:=strings.Index(line,"#"); idx>=0 { line=strings.TrimSpace(line[:idx]) }
        fields:=strings.Fields(line); if len(fields)<2 { continue }
        key:=strings.Trim(fields[0],"'") ; icon:=fields[1]
        if len(key)==2 && !strings.ContainsAny(key,"*.") && !inPatterns { typeIcons[key]=icon; continue }
        inPatterns=true; rules=append(rules,iconRule{key,icon})
    }
    return rules,typeIcons
}

func (a *app) iconFor(e entry) string {
    if e.isDir { if x:=a.fileTypeIcons["di"]; x!="" {return x} }
    if e.info!=nil && e.info.Mode()&0111!=0 { if x:=a.fileTypeIcons["ex"]; x!="" {return x} }
    name:=e.name
    lower:=strings.ToLower(name)
    for _,r:= range a.iconRules {
        pat:=r.pattern
        match:=false
        if strings.HasPrefix(pat,"*.") { match = strings.HasSuffix(lower, strings.ToLower(pat[1:]))
        } else if strings.HasPrefix(pat,"*") { match = strings.HasSuffix(lower, strings.ToLower(pat[1:])) || lower==strings.ToLower(pat[1:]) }
        if match { return r.icon }
    }
    if x:=a.fileTypeIcons["fi"]; x!="" {return x}
    return ""
}

func visWidth(s string) int { return utf8.RuneCountInString(stripANSI(s)) }
func spaces(n int) string { if n<=0 {return ""}; return strings.Repeat(" ",n) }
func truncRunes(s string, w int) string { if w<=0 {return ""}; r:=[]rune(s); if len(r)<=w {return s}; return string(r[:w]) }
func tailRunes(s string, w int) string { if w<=0 {return ""}; r:=[]rune(s); if len(r)<=w {return s}; return string(r[len(r)-w:]) }

func stripANSI(s string) string {
    var b strings.Builder
    for i:=0;i<len(s);i++ {
        if s[i]==0x1b {
            i++
            if i<len(s) && s[i]=='[' { for i<len(s) && (s[i]<'@' || s[i]>'~') { i++ } }
            continue
        }
        b.WriteByte(s[i])
    }
    return b.String()
}

